# add cleanup to sender stripe just before method closes: target unique occurrence after inner try.
s=s.replace('''                if (!entry.id.equals(ack.fileId) || ack.offset != entry.size) {\n                    throw new java.io.IOException("Invalid striped completion acknowledgement");\n                }\n            }\n        }\n    }''','''                if (!entry.id.equals(ack.fileId) || ack.offset != entry.size) {\n                    throw new java.io.IOException("Invalid striped completion acknowledgement");\n                }\n            }\n        } finally {\n            // try-with-resources already closed the socket; remove the stale handle.\n            openSockets.removeIf(Socket::isClosed);\n        }\n    }''',1)
s=s.replace('''        final CountDownLatch published = new CountDownLatch(1);\n        final Object fileLock''','''        final CountDownLatch published = new CountDownLatch(1);\n        final java.util.concurrent.atomic.AtomicBoolean completionDelivered = new java.util.concurrent.atomic.AtomicBoolean(false);\n        final Object fileLock''',1)
